import math


def calculate(left: float, operator: str, right: float) -> float:
    """Calculate one operation, rejecting invalid operators and zero divisors."""
    if operator == "+":
        return left + right
    if operator == "-":
        return left - right
    if operator == "*":
        return left * right
    if operator == "/":
        if right == 0:
            raise ValueError("Cannot divide by zero.")
        return left / right
    raise ValueError("Choose +, -, *, or /.")


def read_number(prompt: str, last_result: float = None) -> float:
    """Read a finite number, allowing the user to retry invalid input. Accepts 'ans' to reuse last result."""
    while True:
        try:
            user_input = input(prompt)
            if user_input.strip().lower() in {"q", "quit", "exit"}:
                raise EOFError
            if user_input.strip().lower() == "ans":
                if last_result is not None:
                    return last_result
                else:
                    print("No previous answer available.")
                    continue
            number = float(user_input)
            if math.isfinite(number):
                return number
        except ValueError:
            pass
        except EOFError:
            raise
        print("Please enter a finite number.")


def main() -> None:
    print("Calculator: +, -, *, / (enter q to quit)")
    last_result = None
    try:
        while True:
            operator = input("Operation: ").strip().lower()
            if operator in {"q", "quit", "exit"}:
                break
            if operator not in {"+", "-", "*", "/"}:
                print("Choose +, -, *, or /.")
                continue
            try:
                left = read_number("First number: ", last_result)
                right = read_number("Second number: ", last_result)
                result = calculate(left, operator, right)
                print(f"Result: {result:g}")
                last_result = result
            except ValueError as error:
                print(error)
            except (EOFError, KeyboardInterrupt):
                print()
                break
    except (EOFError, KeyboardInterrupt):
        print()
    print("Goodbye!")


if __name__ == "__main__":
    main()

